import {appendBankPayment} from './admin-bank-payment.mjs?v=2';
import {appendPFReview} from './admin-pf-review.mjs';
import {matchesOrder} from './order-search.mjs';
import {appendOrderSummaryInfo,appendOrderSummaryState} from './admin-order-summary.mjs';
import {orderKind,isTestOrder,nextStep,dateTime,paymentLabel,orderLabels} from './admin-order-state.mjs';
import {mockupsForCheckout,mockupsForPfOrder,appendMockupOverview} from './admin-mockups.mjs?v=4';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n;};
export function isUnfinishedPayment(checkout,pfs=[]){return !pfs.length&&!checkout.pfOrderIds?.length&&!checkout.paidAt&&['prepared','payment_setup','payment_setup_uncertain','awaiting_payment','expired','payment_failed','cancelled'].includes(checkout.status);}
export function orderList(orders,checkouts,shipmentMails=[]){const panel=el('section',null,'order-workspace'),tools=el('div',null,'order-tools'),search=el('input'),tests=el('input'),label=el('label'),list=el('div');search.type='search';search.placeholder='Søg kunde, produkt eller ordrenummer';search.setAttribute('aria-label','Søg ordrer');tests.type='checkbox';label.append(tests,document.createTextNode('Vis testordrer'));tools.append(search,label);panel.append(tools,list);const records=[...checkouts.map(c=>({checkout:c,pfs:orders.filter(o=>o.checkoutId===c.id)})),...orders.filter(o=>!checkouts.some(c=>c.id===o.checkoutId)).map(o=>({pfs:[o]}))].sort((a,b)=>String(b.checkout?.createdAt||b.pfs[0]?.createdAt).localeCompare(String(a.checkout?.createdAt||a.pfs[0]?.createdAt)));
function render(){list.replaceChildren();let count=0;const attempts=el('details',null,'orders-secondary'),attemptList=el('div');let attemptCount=0;for(const r of records){const c=r.checkout,o=r.pfs[0]||{},kind=orderKind(o,c),shipping=c?.shipping||o.shipping||{},lines=c?.lines||o.lines||[];if((!tests.checked&&isTestOrder(o,c))||!matchesOrder(search.value,{checkout:c,orders:r.pfs}))continue;if(c&&isUnfinishedPayment(c,r.pfs)){attemptCount++;const row=el('article',null,'order-card'),open=el('button','Åbn betalingsdetaljer');open.type='button';open.onclick=()=>{const target=document.getElementById('checkout-'+c.id);if(!target)return;for(let node=target;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;target.scrollIntoView({block:'start',behavior:'smooth'});};row.append(el('strong',shipping.name||shipping.email||c.id),el('p',dateTime(c.createdAt)+' · '+paymentLabel(c)),el('small',c.status==='cancelled'?'Annulleret betalingsforsøg · historik bevaret':'Uafsluttet betalingsforsøg · ingen PF-ordre'),open);attemptList.append(row);continue;}count++;const row=el('article',null,'order-summary-card'),gallery=el('div'),info=el('div'),state=el('div');appendMockupOverview(gallery,c?mockupsForCheckout(c):mockupsForPfOrder(null,o),{decorated:lines.some(l=>l.decorations?.length)});appendOrderSummaryInfo(info,{checkout:c,orders:r.pfs,lines});appendOrderSummaryState(state,c,r.pfs);if(c){row.id='checkout-review-'+c.id;appendPFReview(state,c);appendBankPayment(state,c);}for(const p of r.pfs){const a=el('a','Åbn ordre','action light');a.href='/admin/pf-orders#order='+encodeURIComponent(p.id);const task=nextStep(p,c,shipmentMails);if(task[0]==='Smerch')state.append(el('small',task.join(' · ')));state.append(a);}if(!r.pfs.length)state.append(el('p',c?.pfHandoff?.reason||'Ingen PF-ordre tilknyttet. Se betalingsdetaljer nedenfor.'));row.append(gallery,info,state);list.append(row);}if(!count)list.append(el('p','Ingen ordrer i denne visning. Slå “Vis testordrer” til for at se jeres tests.','muted'));if(attemptCount){attempts.append(el('summary',`Betalingsforsøg · ikke bestilte ordrer (${attemptCount})`),attemptList);list.append(attempts);}}search.oninput=tests.onchange=render;render();const reviewId=sessionStorage.getItem('smerch-review-checkout');if(reviewId){sessionStorage.removeItem('smerch-review-checkout');requestAnimationFrame(()=>document.getElementById('checkout-review-'+reviewId)?.scrollIntoView({block:'center'}));}return panel;}
